import React, {
    useEffect,
    useState,
} from "react";

const getMovesetPath = (battleMode) =>
    battleMode === "singles"
        ? "/singles/csv_movesets/"
        : "/doubles/csv_movesets/";

export default function PokemonBuildPanel({
    clickedBuild,
    battleMode,
}) {
    const [
        buildData,
        setBuildData,
    ] = useState(null);

    const MOVESET_PATH =
        getMovesetPath(battleMode);

    const normalize = (str) =>
        str
            ?.toLowerCase()
            .replace(
                /[^a-z0-9]/g,
                ""
            )
            .trim() || "";

    const loadCSV = async (
        path
    ) => {
        const res =
            await fetch(path);
        return await res.text();
    };

    const parseCSV = (
        text
    ) =>
        text
            .trim()
            .split(/\r?\n/)
            .slice(1)
            .map((r) =>
                r.split(
                    /,(?=(?:(?:[^"]*"){2})*[^"]*$)/
                )
            );

    useEffect(() => {
        if (
            !clickedBuild ||
            !clickedBuild.sourceFile
        ) {
            setBuildData(null);
            return;
        }

        const loadBuild =
            async () => {
                const text =
                    await loadCSV(
                        MOVESET_PATH +
                        clickedBuild.sourceFile
                    );

                const rows =
                    parseCSV(text);

                const pokemonRows =
                    rows.filter(
                        (r) =>
                            normalize(
                                r[1]
                            ) ===
                            normalize(
                                clickedBuild.pokemon
                            )
                    );

                const grouped =
                    {};

                for (let row of pokemonRows) {
                    const category =
                        row[2];

                    const itemName =
                        category ===
                            "Stats"
                            ? row[3]
                            : row[4];

                    const usage =
                        row[5];

                    if (
                        category ===
                        "Stats" &&
                        [
                            "Raw count",
                            "Avg. weight",
                            "Viability Ceiling",
                        ].includes(
                            itemName
                        )
                    )
                        continue;

                    if (!itemName)
                        continue;

                    if (
                        !grouped[
                        category
                        ]
                    )
                        grouped[
                            category
                        ] = [];

                    grouped[
                        category
                    ].push({
                        name:
                            itemName,
                        usage,
                    });
                }

                Object.keys(
                    grouped
                ).forEach(
                    (
                        cat
                    ) => {
                        grouped[
                            cat
                        ] =
                            grouped[
                                cat
                            ]
                                .sort(
                                    (
                                        a,
                                        b
                                    ) =>
                                        Number(
                                            b.usage
                                        ) -
                                        Number(
                                            a.usage
                                        )
                                )
                                .slice(
                                    0,
                                    5
                                );
                    }
                );

                setBuildData({
                    display:
                        clickedBuild.display,
                    month:
                        clickedBuild.month,
                    data: grouped,
                });
            };

        loadBuild();
    }, [
        clickedBuild,
        MOVESET_PATH,
    ]);

    if (!buildData) {
        return (
            <div>
                Click a graph point
                to view build
            </div>
        );
    }

    return (
        <div>
            <h3>
                {
                    buildData.display
                }{" "}
                —{" "}
                {
                    buildData.month
                }
            </h3>

            {Object.entries(
                buildData.data
            ).map(
                ([
                    category,
                    items,
                ]) => (
                    <div
                        key={
                            category
                        }
                    >
                        <strong>
                            {
                                category
                            }
                        </strong>
                        <ul>
                            {items.map(
                                (
                                    item,
                                    idx
                                ) => (
                                    <li
                                        key={
                                            idx
                                        }
                                    >
                                        {
                                            item.name
                                        }{" "}
                                        (
                                        {
                                            item.usage
                                        }
                                        %)
                                    </li>
                                )
                            )}
                        </ul>
                    </div>
                )
            )}
        </div>
    );
}
